def load_ui_config() -> dict:
    try:
        with open(UI_CONFIG_FILE, "r", encoding="utf-8") as fh:
            data = json.load(fh)
        return {**UI_DEFAULTS, **(data if isinstance(data, dict) else {})}
    except (OSError, json.JSONDecodeError):
        return dict(UI_DEFAULTS)

def save_ui_config(data: dict) -> None:
    tmp = UI_CONFIG_FILE + ".tmp"
    with open(tmp, "w", encoding="utf-8") as fh:
        json.dump(data, fh, ensure_ascii=False, indent=2)
    os.replace(tmp, UI_CONFIG_FILE)

def ui_config_value(key: str):
    return load_ui_config().get(key, UI_DEFAULTS.get(key))

def ui_button_style(value: str):
    return {"success": "success", "primary": "primary", "danger": "danger"}.get(str(value), "success")

async def admin_ui_settings_menu(target):
    text = ("⚙️ <b>Update / Payment Proof / Join Log সেটিংস</b>\n\n"
            "এখান থেকে চ্যানেল ID, URL বাটন, বাটনের কালার এবং ছবি পরিবর্তন করুন।")
    rows = [
        [b("📢 Update Channel ID", "uic:update_channel_id"), b("🔗 Update URL", "uic:update_url")],
        [b("✏️ Update Button Text", "uic:update_button_text"), b("🎨 Update Button Color", "uic:update_button_color")],
        [b("🖼️ Update Photo", "uiph:update_photo")],
        [b("💳 Payment Proof Channel ID", "uic:proof_channel_id"), b("🔗 Proof URL", "uic:proof_url")],
        [b("✏️ Proof Button Text", "uic:proof_button_text"), b("🎨 Proof Button Color", "uic:proof_button_color")],
        [b("🖼️ Payment Proof Photo", "uiph:proof_photo")],
        [b("🟢 Join Log Channel ID (নতুন সেটিং)", "uic:join_log_channel_id")],
        [back_btn("admin", "⬅️ এডমিন প্যানেল")],
    ]
    if isinstance(target, CallbackQuery):
        try: await target.message.edit_text(text, reply_markup=kb(*rows))
        except TelegramAPIError: await target.message.answer(text, reply_markup=kb(*rows))
    else:
        await target.answer(text, reply_markup=kb(*rows))

async def send_bot_update(text, photo_path="update_logo.jpg"):
    cfg = load_ui_config()
    caption = ("🚀 <b>MICRO TASK UPDATE</b>\n━━━━━━━━━━━━━━━━\n"
               f"{html_lib.escape(str(text))}\n━━━━━━━━━━━━━━━━\n👇 নিচে ক্লিক করে কাজ শুরু করুন")
    button_text = str(cfg.get("update_button_text") or "✅ কাজ শুরু করুন")
    button_url = str(cfg.get("update_url") or BOT_LINK)
    style = ui_button_style(cfg.get("update_button_color", "success"))
    markup = InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text=button_text, url=button_url, style=style)]])
    photo_setting = str(cfg.get("update_photo") or "").strip()
    try:
        chat_id = int(cfg.get("update_channel_id") or UPDATE_CHANNEL_ID)
        if photo_setting:
            photo = photo_setting  # Telegram file_id or URL
        elif photo_path and os.path.isfile(photo_path):
            photo = FSInputFile(photo_path)
        else:
            photo = BufferedInputFile(base64.b64decode(_UPDATE_LOGO_BASE64), filename="update_logo.jpg")
        await bot.send_photo(chat_id=chat_id, photo=photo, caption=caption, reply_markup=markup)
    except (TelegramAPIError, ValueError, TypeError) as exc:
        print(f"[UPDATE CHANNEL ERROR] {exc}")

