def esc(text) -> str:
    return html_lib.escape(str(text if text is not None else ""))


def taka(value) -> str:
    try:
        return f"৳{float(value):,.2f}"
    except (TypeError, ValueError):
        return "৳0.00"


def head(emoji: str, title: str, sub: str = "") -> str:
    out = f"{DIV}\n{emoji} <b>{title}</b>\n"
    if sub:
        out += f"<i>{sub}</i>\n"
    out += DIV
    return out


def box(lines, title: str = "", emoji: str = "📦") -> str:
    out = ""
    if title:
        out += f"┏━━〔 {emoji} <b>{title}</b> 〕━━┓\n"
    for line in lines:
        out += f"┃ {line}\n"
    if title:
        out += "┗━━━━━━━━━━━━━━━━━┛"
    return out


# ══════════════ বাটনের ব্যাকগ্রাউন্ড কালার (Telegram Bot API `style`) ══════════════
# Telegram শুধু ৩টি নেটিভ কালার দেয়:  primary = 🔵 নীল | success = 🟢 সবুজ | danger = 🔴 লাল
# (style না দিলে বাটন ডিফল্ট ধূসর থাকে — ব্যাক/হোম/পেজ বাটনে ইচ্ছা করেই ধূসর রাখা হয়েছে)
# পুরোনো Telegram অ্যাপে style সাপোর্ট না থাকলে বাটন স্বাভাবিকভাবেই কাজ করবে, শুধু রঙ দেখা যাবে না।
BLUE, GREEN, RED = "primary", "success", "danger"

_DANGER_CB = ("proofcancel", "pno:", "dno:", "wno:", "tdel:", "catdel:", "offdel:", "admindel:", "uban:", "ubalm:")
_DANGER_TXT = ("বাতিল", "রিজেক্ট", "ডিলিট", "রিমুভ", "মাইনাস", "ব্যান করুন", "🔴")
_GREEN_CB = ("pok:", "dok:", "wok:", "aconfirm", "depconfirm", "proofdone", "proof:", "task:", "atask", "ubalp:",
             "offadd", "catadd", "addadmin", "depm:", "wdm:", "acat:", "amy:0")
_GREEN_TXT = ("এপ্রুভ", "কনফার্ম", "পেইড", "🟢", "আনবান", "সাবমিট", "পাবলিশ")
_PLAIN_TXT = ("🏠", "⬅️", "➡️", "📄", "পরেরটি", "আগেরটি")


def auto_style(text: str, cb: str = ""):
    """বাটনের লেখা ও callback দেখে স্বয়ংক্রিয়ভাবে কালার ঠিক করে।"""
    if text.startswith(_PLAIN_TXT):
        return None
    if cb.startswith(_DANGER_CB) or any(w in text for w in _DANGER_TXT):
        return RED
    if cb.startswith(_GREEN_CB) or any(w in text for w in _GREEN_TXT) or cb == "cat:0":
        return GREEN
    return BLUE


def b(text: str, cb: str, style="auto") -> InlineKeyboardButton:
    st = auto_style(text, cb) if style == "auto" else style
    extra = {"style": st} if st else {}
    return InlineKeyboardButton(text=text, callback_data=cb, **extra)


def ub(text: str, url: str, style=GREEN) -> InlineKeyboardButton:
    extra = {"style": style} if style else {}
    return InlineKeyboardButton(text=text, url=url, **extra)


def rkb(text: str, style=None) -> KeyboardButton:
    """রিপ্লাই (নিচের মেনু) কীবোর্ড বাটন — কালারসহ।"""
    extra = {"style": style} if style else {}
    return KeyboardButton(text=text, **extra)


def kb(*rows) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup(inline_keyboard=[list(r) for r in rows if r])


def grid(buttons, per_row: int = 2):
    """বাটনের লিস্টকে সুন্দরভাবে সারি করে সাজায় (ডিফল্ট: প্রতি সারিতে ২টি)।"""
    buttons = list(buttons)
    return [buttons[i:i + per_row] for i in range(0, len(buttons), per_row)]


def now() -> str:
    return datetime.now().strftime("%d-%m-%Y %H:%M")


def short_date(value) -> str:
    if not value:
        return "-"
    return str(value)[0:16]


# ══════════════════════════ ডাটাবেস ══════════════════════════
def connect() -> sqlite3.Connection:
    conn = sqlite3.connect(DB_PATH, timeout=30)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("PRAGMA foreign_keys=ON")
    return conn


def q(sql: str, params: tuple = (), one: bool = False):
    conn = connect()
    try:
        cur = conn.execute(sql, params)
        conn.commit()
        rows = cur.fetchall()
        return (rows[0] if rows else None) if one else rows
    finally:
        conn.close()


def insert_id(sql: str, params: tuple = ()) -> int:
    """Execute an INSERT and return its ID from the same SQLite connection."""
    conn = connect()
    try:
        cur = conn.execute(sql, params)
        conn.commit()
        return int(cur.lastrowid or 0)
    finally:
        conn.close()


def init_db() -> None:
    conn = connect()
    cur = conn.cursor()
    cur.executescript(
        """
        CREATE TABLE IF NOT EXISTS users(
            id INTEGER PRIMARY KEY,
            username TEXT DEFAULT '',
            first_name TEXT DEFAULT '',
            balance REAL DEFAULT 0,
            total_earn REAL DEFAULT 0,
            total_deposit REAL DEFAULT 0,
            total_withdraw REAL DEFAULT 0,
            referred_by INTEGER DEFAULT 0,
            refer_count INTEGER DEFAULT 0,
            is_agent INTEGER DEFAULT 0,
            is_banned INTEGER DEFAULT 0,
            joined_at TEXT,
            last_seen TEXT
        );
        CREATE TABLE IF NOT EXISTS admins(
            id INTEGER PRIMARY KEY,
            added_by INTEGER DEFAULT 0,
            added_at TEXT
        );
        CREATE TABLE IF NOT EXISTS categories(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT,
            emoji TEXT DEFAULT '📁',
            is_active INTEGER DEFAULT 1
        );
        CREATE TABLE IF NOT EXISTS tasks(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            category_id INTEGER DEFAULT 1,
            title TEXT,
            description TEXT DEFAULT '',
            link TEXT DEFAULT '',
            reward REAL DEFAULT 0,
            slots INTEGER DEFAULT 1,
            done INTEGER DEFAULT 0,
            created_by INTEGER DEFAULT 0,
            creator_role TEXT DEFAULT 'admin',
            is_active INTEGER DEFAULT 1,
            created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS task_done(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            task_id INTEGER,
            user_id INTEGER,
            status TEXT DEFAULT 'pending',
            note TEXT DEFAULT '',
            submitted_at TEXT,
            decided_at TEXT,
            decided_by INTEGER DEFAULT 0,
            UNIQUE(task_id, user_id)
        );
        CREATE TABLE IF NOT EXISTS proofs(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            done_id INTEGER,
            file_id TEXT,
            created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS task_requirements(
            id INTEGER PRIMARY KEY AUTOINCREMENT, task_id INTEGER, position INTEGER DEFAULT 0,
            kind TEXT DEFAULT 'text', prompt TEXT DEFAULT ''
        );
        CREATE TABLE IF NOT EXISTS task_answers(
            id INTEGER PRIMARY KEY AUTOINCREMENT, done_id INTEGER, requirement_id INTEGER,
            prompt TEXT DEFAULT '', kind TEXT DEFAULT 'text', text_value TEXT DEFAULT '',
            file_id TEXT DEFAULT '', created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS proof_drafts(
            user_id INTEGER PRIMARY KEY, data TEXT DEFAULT '', ts REAL DEFAULT 0
        );
        CREATE TABLE IF NOT EXISTS category_shares(
            category_id INTEGER PRIMARY KEY, user_percent REAL DEFAULT 66.6667
        );
        CREATE TABLE IF NOT EXISTS deposits(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER,
            method TEXT,
            amount REAL DEFAULT 0,
            credit REAL DEFAULT 0,
            trx_id TEXT DEFAULT '',
            sender_number TEXT DEFAULT '',
            file_ids TEXT DEFAULT '',
            status TEXT DEFAULT 'pending',
            note TEXT DEFAULT '',
            created_at TEXT,
            decided_at TEXT
        );
        CREATE TABLE IF NOT EXISTS withdrawals(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER,
            method TEXT,
            amount REAL DEFAULT 0,
            account_no TEXT DEFAULT '',
            status TEXT DEFAULT 'pending',
            note TEXT DEFAULT '',
            created_at TEXT,
            decided_at TEXT
        );
        CREATE TABLE IF NOT EXISTS offers(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT,
            body TEXT DEFAULT '',
            is_active INTEGER DEFAULT 1,
            created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS notifications(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER,
            title TEXT,
            body TEXT DEFAULT '',
            is_read INTEGER DEFAULT 0,
            created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS settings(
            key TEXT PRIMARY KEY,
            value TEXT
        );
        CREATE TABLE IF NOT EXISTS ledger(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER,
            kind TEXT,
            amount REAL DEFAULT 0,
            note TEXT DEFAULT '',
            created_at TEXT
        );
        """
    )
    for key, value in DEFAULT_SETTINGS.items():
        cur.execute("INSERT OR IGNORE INTO settings(key, value) VALUES(?, ?)", (key, value))
    for tid in ADMIN_IDS:
        cur.execute("INSERT OR IGNORE INTO admins(id, added_by, added_at) VALUES(?, 0, ?)", (int(tid), now()))
    if cur.execute("SELECT COUNT(*) AS c FROM categories").fetchone()[0] == 0:
        for name, emoji in DEFAULT_CATEGORIES:
            cur.execute("INSERT INTO categories(name, emoji) VALUES(?, ?)", (name, emoji))
    conn.commit()
    conn.close()


