# ══════════════════════════ সেটিংস হেল্পার ══════════════════════════
def get_setting(key: str, default: str = "0") -> str:
    row = q("SELECT value FROM settings WHERE key=?", (key,), one=True)
    return row["value"] if row and row["value"] is not None else default


def set_setting(key: str, value) -> None:
    q(
        "INSERT INTO settings(key, value) VALUES(?, ?) "
        "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
        (key, str(value)),
    )


def setting_float(key: str, default: float = 0.0) -> float:
    try:
        return float(get_setting(key, str(default)))
    except ValueError:
        return default


def premium_emoji_markup(text):
    """Prefix outgoing bot text/captions with the admin-configured emoji."""
    if not isinstance(text, str) or not text or get_setting("premium_emoji_enabled", "1") != "1":
        return text
    value = get_setting("premium_emoji_value", "💎").strip() or "💎"
    # Numeric input is treated as a Telegram custom emoji ID (HTML parse mode required).
    if value.isdigit():
        prefix = f'<tg-emoji emoji-id="{value}">💎</tg-emoji> '
    else:
        prefix = esc(value) + " "
    if text.startswith(prefix) or "<tg-emoji" in text[:120]:
        return text
    return prefix + text


def install_premium_emoji_hooks() -> None:
    """Central hook for text and media captions sent or edited through aiogram Bot."""
    def wrap(method_name, text_field=None, positional_index=None):
        original = getattr(Bot, method_name, None)
        if original is None or getattr(original, "_premium_emoji_wrapped", False):
            return

        async def wrapped(self, *args, **kwargs):
            args = list(args)
            # Prefer keyword arguments because aiogram normally calls Bot methods by keyword.
            if text_field and isinstance(kwargs.get(text_field), str):
                kwargs[text_field] = premium_emoji_markup(kwargs[text_field])
            elif positional_index is not None and len(args) > positional_index and isinstance(args[positional_index], str):
                args[positional_index] = premium_emoji_markup(args[positional_index])
            return await original(self, *args, **kwargs)

        wrapped._premium_emoji_wrapped = True
        wrapped.__name__ = getattr(original, "__name__", method_name)
        setattr(Bot, method_name, wrapped)

    wrap("send_message", "text", 1)
    wrap("edit_message_text", "text", 2)
    for method in ("send_photo", "send_video", "send_animation", "send_document", "send_audio", "send_voice", "send_video_note"):
        wrap(method, "caption", 2)
    wrap("edit_message_caption", "caption", 2)


# Install only after the formatter and installer have both been defined.
install_premium_emoji_hooks()


def payment_method_enabled(method: str) -> bool:
    """Payment method availability is stored in SQLite and survives restarts."""
    if method not in PAYMENT_METHODS:
        return False
    if PAYMENT_METHODS[method].get("type") == "auto" and not crypto_ready():
        return False  # PRIVATE_KEY/web3 ঠিক না থাকলে অটো মেথড ইউজারদের কাছে দেখাবে না
    return get_setting(f"payment_enabled_{method}", "1") == "1"


def category_user_percent(category_id: int) -> float:
    row = q("SELECT user_percent FROM category_shares WHERE category_id=?", (int(category_id),), one=True)
    value = float(row["user_percent"]) if row else setting_float("agent_user_percent", 66.6667)
    return max(0.0, min(100.0, value))


