async def notify_admins_action(text: str, markup: InlineKeyboardMarkup, photos=None) -> None:
    ids = set(int(x) for x in ADMIN_IDS)
    for row in q("SELECT id FROM admins"):
        ids.add(int(row["id"]))
    photo_ids = list(photos or [])[:10]
    for tg_id in ids:
        try:
            if not photo_ids:
                await bot.send_message(tg_id, text, reply_markup=markup)
                continue
            await bot.send_message(tg_id, text)
            for idx, fid in enumerate(photo_ids):
                try:
                    # এপ্রুভ/রিজেক্ট বাটন শেষ প্রমাণ ছবির ঠিক নিচে থাকবে
                    await bot.send_photo(tg_id, fid, reply_markup=markup if idx == len(photo_ids)-1 else None)
                except (TelegramBadRequest, TelegramAPIError) as exc:
                    try:
                        await bot.send_message(tg_id, f"⚠️ ছবি পাঠানো যায়নি। Telegram error: <code>{esc(str(exc)[:180])}</code>", reply_markup=markup if idx == len(photo_ids)-1 else None)
                    except (TelegramBadRequest, TelegramAPIError):
                        pass
        except (TelegramForbiddenError, TelegramBadRequest, TelegramAPIError):
            pass


async def broadcast(text: str, photo: str = "", skip: int = 0) -> int:
    ok = 0
    rows = q("SELECT id FROM users WHERE is_banned=0")
    for row in rows:
        tg_id = int(row["id"])
        if tg_id == skip:
            continue
        try:
            if photo:
                await bot.send_photo(tg_id, photo, caption=text)
            else:
                await bot.send_message(tg_id, text, reply_markup=main_menu(tg_id))
            ok += 1
        except (TelegramForbiddenError, TelegramBadRequest, TelegramAPIError):
            pass
        await asyncio.sleep(0.045)
    return ok


async def send_photos(chat_id: int, file_ids: str, caption: str) -> None:
    ids = [x for x in (file_ids or "").split(",") if x]
    if not ids:
        try:
            await bot.send_message(chat_id, "🖼️ কোনো ছবি পাওয়া যায়নি।")
        except (TelegramBadRequest, TelegramAPIError):
            pass
        return
    for fid in ids[:10]:
        try:
            await bot.send_photo(chat_id, fid, caption=caption)
            caption = ""
        except (TelegramBadRequest, TelegramAPIError) as exc:
            try:
                await bot.send_message(chat_id, f"⚠️ ছবি পাঠানো যায়নি। Telegram error: <code>{esc(str(exc)[:180])}</code>")
            except (TelegramBadRequest, TelegramAPIError):
                pass
        await asyncio.sleep(0.3)


