def custom_reply(key: str, tg_id: int = 0):
    """এডমিন কোনো বাটনের রিপ্লাই বদলালে সেই টেক্সট (প্লেসহোল্ডারসহ) ফেরত দেয়, নাহলে None।"""
    text = get_setting(f"btn_reply:{key}", "")
    if not text or not text.strip():
        return None
    user = get_user(tg_id) if tg_id else None
    values = {
        "{name}": esc((user["first_name"] if user else "") or "বন্ধু"),
        "{id}": str(tg_id or ""),
        "{balance}": taka(user["balance"]) if user else taka(0),
        "{earn}": taka(user["total_earn"]) if user else taka(0),
        "{refer_count}": str(int(user["refer_count"] or 0)) if user else "0",
        "{bonus}": taka(setting_float("refer_bonus", 20)),
        "{min_withdraw}": taka(setting_float("min_withdraw", 100)),
        "{support}": "@" + esc(get_setting("support_username", "support")),
    }
    for token, val in values.items():
        text = text.replace(token, val)
    return text


