# ══════════════════════════ প্রমাণের ধাপ পার্সার ══════════════════════════
_PHOTO_KEYS = ("photo", "image", "img", "pic", "picture", "screenshot", "ss", "ছবি", "ফটো", "স্ক্রিনশট", "স্ক্রিন শট", "স্কিনশট", "ছবির প্রমাণ")
_TEXT_KEYS = ("text", "txt", "টেক্সট", "লেখা", "লিখিত", "লিখুন", "লিখে")
_KIND_WORDS = sorted(_PHOTO_KEYS + _TEXT_KEYS, key=len, reverse=True)
_KIND_ALT = "|".join(re.escape(w) for w in _KIND_WORDS)
_KIND_MARK = re.compile(r"(?i)(?:^|(?<=[\s,;|।]))(" + _KIND_ALT + r")\s*[:：]\s*")
_NUM_PREFIX = re.compile(r"^\s*(?:[-–—•*▪➤➡✅📌▶►]+\s*|\(?[0-9০-৯]{1,2}\s*[\)\.\-:।]\s*)")


def parse_requirements(raw: str) -> list:
    """এজেন্টের লেখা থেকে ধাপ তৈরি করে। এক লাইনে একাধিক 'text:'/'photo:' থাকলেও আলাদা ধাপ হবে।"""
    segments = []
    for line in [x.strip() for x in (raw or "").splitlines() if x.strip()]:
        for part in re.split(r"[;|；]", line):
            part = _NUM_PREFIX.sub("", part.strip())
            if not part:
                continue
            marks = list(_KIND_MARK.finditer(part))
            if len(marks) > 1:
                starts = [m.start() for m in marks]
                if starts[0] > 0:
                    segments.append(part[:starts[0]].strip(" ,"))
                for i, s in enumerate(starts):
                    end = starts[i + 1] if i + 1 < len(starts) else len(part)
                    segments.append(part[s:end].strip(" ,"))
            else:
                segments.append(part)
    reqs = []
    for seg in segments:
        seg = seg.strip()
        if not seg:
            continue
        m = _KIND_MARK.match(seg)
        if m:
            word = m.group(1).lower()
            kind = "photo" if word in _PHOTO_KEYS else "text"
            prompt = seg[m.end():].strip()
            if not prompt:
                prompt = "কাজের স্ক্রিনশট দিন" if kind == "photo" else "আপনার উত্তর লিখুন"
        else:
            prompt = seg
            low = prompt.lower()
            kind = "photo" if any(w in low for w in _PHOTO_KEYS) else "text"
        reqs.append({"kind": kind, "prompt": prompt[:180]})
        if len(reqs) >= 10:
            break
    return reqs


def steps_overview(reqs: list) -> str:
    return "\n".join(f"{i}. {'📸' if r['kind'] == 'photo' else '✍️'} {esc(r['prompt'])}" for i, r in enumerate(reqs, 1))


