# ══════════════════════════ কপি সিস্টেম ══════════════════════════
def copy_text(label: str, value: str, emoji: str = "📋") -> str:
    return (
        f"{DIV}\n{emoji} <b>{label}</b>\n{DIV}\n\n"
        f"<code>{esc(value)}</code>\n\n"
        "👆 <b>উপরের কোড বক্সে একবার ট্যাপ করলেই কপি হয়ে যাবে ✅</b>\n\n"
        f"🔗 ভ্যালু: <b>{esc(value)}</b>"
    )


async def send_copy(target, label: str, value: str, emoji: str = "📋") -> None:
    text = copy_text(label, value, emoji)
    try:
        if isinstance(target, CallbackQuery):
            await target.message.answer(text)
            await target.answer("✅ কপি বক্স পাঠানো হয়েছে")
        else:
            await target.answer(text)
    except (TelegramBadRequest, TelegramAPIError):
        pass



# ═══════════════════ নতুন ফিচার: চ্যানেল ম্যানেজমেন্ট ═══════════════════
def load_force_channels() -> list:
    """চ্যানেল কনফিগ আলাদা JSON-এ রাখে; মূল SQLite ডাটাবেস স্পর্শ করে না।"""
    try:
        with open(CHANNELS_FILE, "r", encoding="utf-8") as fh:
            data = json.load(fh)
        return data if isinstance(data, list) else []
    except (FileNotFoundError, json.JSONDecodeError, OSError):
        return []


def save_force_channels(channels: list) -> None:
    tmp = CHANNELS_FILE + ".tmp"
    with open(tmp, "w", encoding="utf-8") as fh:
        json.dump(channels, fh, ensure_ascii=False, indent=2)
    os.replace(tmp, CHANNELS_FILE)


def force_join_keyboard(channels: list) -> InlineKeyboardMarkup:
    rows = []
    for ch in channels:
        url = (ch.get("url") or "").strip()
        title = (ch.get("title") or ch.get("chat_id") or "চ্যানেল").strip()
        if url:
            rows.append([ub("📢 " + title[:50] + " — Join", url)])
    rows.append([b("✅ আমি জয়েন করেছি — চেক করুন", "fjcheck", GREEN)])
    return kb(*rows)


async def missing_force_channels(user_id: int) -> list:
    missing = []
    for ch in load_force_channels():
        try:
            member = await bot.get_chat_member(chat_id=ch["chat_id"], user_id=user_id)
            if member.status in ("left", "kicked", "restricted"):
                missing.append(ch)
        except (TelegramAPIError, KeyError, TypeError) as exc:
            print("force-join check failed:", ch.get("chat_id"), exc)
            missing.append(ch)
    return missing


class ForceJoinMiddleware(BaseMiddleware):
    async def __call__(self, handler, event, data):
        user = getattr(event, "from_user", None)
        if user is None or is_admin(user.id):
            return await handler(event, data)
        # Force-join চেক বাটনটি নিজে চলতে দিতে হবে, নইলে ইউজার জয়েন যাচাই করতে পারবে না।
        if isinstance(event, CallbackQuery) and event.data == "fjcheck":
            return await handler(event, data)
        if isinstance(event, ChatMemberUpdated):
            return await handler(event, data)
        missing = await missing_force_channels(user.id)
        if not missing:
            return await handler(event, data)
        markup = force_join_keyboard(missing)
        notice = "🔒 <b>বট ব্যবহার করতে আগে নিচের সব চ্যানেলে জয়েন করুন।</b>\n\nজয়েন করার পর “আমি জয়েন করেছি” চাপুন।"
        try:
            if isinstance(event, Message):
                await event.answer(notice, reply_markup=markup)
            elif isinstance(event, CallbackQuery):
                await event.answer("আগে সব চ্যানেলে জয়েন করুন।", show_alert=True)
                if event.message:
                    await event.message.answer(notice, reply_markup=markup)
        except TelegramAPIError:
            pass
        return None


dp.message.outer_middleware(ForceJoinMiddleware())
dp.callback_query.outer_middleware(ForceJoinMiddleware())


@dp.callback_query(F.data == "fjcheck")
async def cb_force_join_check(call: CallbackQuery) -> None:
    missing = await missing_force_channels(call.from_user.id)
    if missing:
        await call.answer("❌ এখনো সব চ্যানেলে জয়েন করা হয়নি।", show_alert=True)
        try:
            await call.message.edit_reply_markup(reply_markup=force_join_keyboard(missing))
        except TelegramAPIError:
            pass
        return
    await call.answer("✅ জয়েন যাচাই সম্পন্ন!")
    await call.message.answer("✅ সব চ্যানেল জয়েন যাচাই হয়েছে। /start চাপুন।", reply_markup=main_menu(call.from_user.id))


