@dp.message(AdminFSM.channel_add)
async def msg_channel_add(message: Message, state: FSMContext) -> None:
    if not is_admin(message.from_user.id):
        await state.clear()
        return
    raw = (message.text or "").strip()
    parts = [x.strip() for x in raw.split("|", 1)]
    if len(parts) != 2 or not parts[0] or not parts[1].startswith(("https://t.me/", "http://t.me/")):
        await message.answer("❌ ফরম্যাট ঠিক নয়। এভাবে দিন:\n<code>@channelusername | https://t.me/channelusername</code>")
        return
    chat_id = parts[0]
    if chat_id.startswith("@"):
        lookup = chat_id
    else:
        try:
            lookup = int(chat_id)
        except ValueError:
            await message.answer("❌ চ্যানেল ID অবশ্যই @username অথবা সংখ্যার ID হতে হবে।")
            return
    try:
        chat = await bot.get_chat(lookup)
        await bot.get_chat_member(chat.id, bot.id)
    except (TelegramAPIError, ValueError) as exc:
        await message.answer("❌ চ্যানেল যাচাই করা যায়নি। বটকে চ্যানেলে admin করুন এবং ID/username পরীক্ষা করুন।")
        print("channel add validation failed:", exc)
        return
    channels = load_force_channels()
    if any(str(x.get("chat_id")) == str(chat.id) for x in channels):
        await message.answer("ℹ️ এই চ্যানেলটি আগে থেকেই তালিকায় আছে।")
        await state.clear()
        return
    channels.append({"chat_id": chat.id, "title": chat.title or chat.username or str(chat.id), "url": parts[1]})
    save_force_channels(channels)
    await state.clear()
    await message.answer(f"✅ চ্যানেল যোগ হয়েছে: <b>{esc(chat.title or chat.id)}</b>\nমোট চ্যানেল: {len(channels)}", reply_markup=kb([b("📢 Channel Management", "chmanage")]))


