@dp.message(F.text == B_AGENT_PROOFS)
async def agent_keyboard_proofs(message: Message, state: FSMContext) -> None:
    await state.clear()
    tg_id = message.from_user.id
    where = "t.created_by=?" if not is_admin(tg_id) else "1=1"
    params = (tg_id,) if not is_admin(tg_id) else ()
    submissions = q(f"SELECT d.id AS done_id, d.status, t.title FROM task_done d JOIN tasks t ON t.id=d.task_id WHERE {where} ORDER BY d.id DESC LIMIT 10", params)
    rows = []
    pending_row = []
    for r in submissions:
        status_icon = '⏳' if r['status']=='pending' else '✅' if r['status']=='approved' else '❌'
        pending_row.append(b(f"{status_icon} #{r['done_id']} • {str(r['title'])[:16]}", f"apview:{r['done_id']}"))
        if len(pending_row) == 2:
            rows.append(pending_row)
            pending_row = []
    if pending_row:
        rows.append(pending_row)
    rows.append([back_btn("agent", "⬅️ এজেন্ট প্যানেল")])
    await message.answer(custom_reply("agent_proofs", tg_id) or "🧾 <b>কাজের প্রমাণ</b>\nযে প্রমাণ দেখতে চান সেটি বেছে নিন:", reply_markup=kb(*rows))


