# ══════════════════════════ প্রমাণ জমা সিস্টেম ══════════════════════════
_PROOF_LOCKS: dict = {}


def proof_lock(user_id: int) -> asyncio.Lock:
    lock = _PROOF_LOCKS.get(user_id)
    if lock is None:
        lock = _PROOF_LOCKS[user_id] = asyncio.Lock()
    return lock


def save_proof_draft(user_id: int, data: dict) -> None:
    payload = json.dumps({k: data.get(k) for k in ("task_id", "reqs", "req_index", "answers")}, ensure_ascii=False)
    q("INSERT INTO proof_drafts(user_id, data, ts) VALUES(?,?,?) "
      "ON CONFLICT(user_id) DO UPDATE SET data=excluded.data, ts=excluded.ts", (user_id, payload, time.time()))


def load_proof_draft(user_id: int, max_age: int = 21600):
    row = q("SELECT data, ts FROM proof_drafts WHERE user_id=?", (user_id,), one=True)
    if not row or time.time() - float(row["ts"] or 0) > max_age:
        return None
    try:
        d = json.loads(row["data"])
    except (ValueError, TypeError):
        return None
    return d if d and d.get("reqs") else None


def clear_proof_draft(user_id: int) -> None:
    q("DELETE FROM proof_drafts WHERE user_id=?", (user_id,))


async def ensure_proof_state(user_id: int, state: FSMContext) -> dict:
    """বট রিস্টার্ট হয়ে স্টেট হারিয়ে গেলেও সেভ করা ড্রাফট থেকে ফিরিয়ে আনে।"""
    data = await state.get_data()
    if data.get("reqs"):
        return data
    draft = load_proof_draft(user_id)
    if not draft:
        return {}
    await state.set_state(ProofFSM.photos)
    await state.set_data({"task_id": draft["task_id"], "reqs": draft["reqs"],
                          "req_index": int(draft.get("req_index") or 0), "answers": draft.get("answers") or []})
    return await state.get_data()


async def ask_proof_step(target: Message, idx: int, reqs: list, prefix: str = "") -> None:
    req = reqs[idx]
    rows = []
    if idx > 0:
        rows.append([b("↩️ আগের ধাপে ফিরুন", "proofback")])
    rows.append([b("❌ বাতিল করুন", "proofcancel")])
    hint = "📸 <b>ছবি (স্ক্রিনশট)</b> পাঠান।" if req["kind"] == "photo" else "✍️ <b>লিখে</b> উত্তর দিন।"
    await target.answer(f"{prefix}📍 <b>ধাপ {idx + 1}/{len(reqs)}</b>\n{esc(req['prompt'])}\n\n{hint}", reply_markup=kb(*rows))


def submit_markup() -> InlineKeyboardMarkup:
    return kb([b("✅ প্রমাণ সাবমিট করুন", "proofdone")], [b("↩️ আগের ধাপে ফিরুন", "proofback")], [b("❌ বাতিল", "proofcancel")])


@dp.callback_query(F.data.startswith("proof:"))
async def cb_proof_start(call: CallbackQuery, state: FSMContext) -> None:
    task_id = int(call.data.split(":")[1]); tg_id = call.from_user.id
    user = get_user(tg_id); task = q("SELECT * FROM tasks WHERE id=?", (task_id,), one=True)
    if not user or user["is_banned"] == 1:
        await call.answer("🚫 আপনার অ্যাকাউন্ট ব্যান!", show_alert=True); return
    if not task or task["is_active"] == 0:
        await call.answer("❌ কাজটি বন্ধ আছে", show_alert=True); return
    if int(task["slots"]) - int(task["done"]) <= 0:
        await call.answer("😔 স্লট শেষ হয়ে গেছে", show_alert=True); return
    existing = q("SELECT id, status FROM task_done WHERE task_id=? AND user_id=?", (task_id, tg_id), one=True)
    if existing and existing["status"] != "rejected":
        await call.answer("⚠️ এই কাজটি আগেই জমা দিয়েছেন!", show_alert=True); return
    reqs = [dict(r) for r in q("SELECT * FROM task_requirements WHERE task_id=? ORDER BY position", (task_id,))]
    if not reqs:
        reqs = [{"id": 0, "kind": "photo", "prompt": "কাজের স্ক্রিনশট দিন"}]
    await state.set_state(ProofFSM.photos)
    await state.set_data({"task_id": task_id, "reqs": reqs, "req_index": 0, "answers": []})
    save_proof_draft(tg_id, await state.get_data())
    intro = (
        f"{DIV}\n🧾 <b>কাজের প্রমাণ জমা দিন</b>\n{DIV}\n\n"
        f"🎯 কাজ: <b>{esc(task['title'])}</b>\n📌 মোট ধাপ: <b>{len(reqs)}</b>টি\n\n"
        f"{steps_overview(reqs)}\n\n"
        "👇 একটি একটি করে ধাপ অনুযায়ী পাঠান। সব ধাপ শেষ হলে <b>সাবমিট</b> বাটন আসবে।\n\n"
    )
    await ask_proof_step(call.message, 0, reqs, prefix=intro)
    await call.answer()


async def save_task_answer(message: Message, state: FSMContext, kind: str, text_value: str = "", file_id: str = "") -> None:
    uid = message.from_user.id
    async with proof_lock(uid):
        data = await ensure_proof_state(uid, state)
        reqs = data.get("reqs", []); idx = int(data.get("req_index", 0))
        if not reqs:
            await state.clear()
            await message.answer("⚠️ প্রমাণ জমার সেশন পাওয়া যায়নি। কাজটি থেকে আবার শুরু করুন।", reply_markup=main_menu(uid))
            return
        if idx >= len(reqs):
            await message.answer("✅ সব ধাপের উত্তর নেওয়া হয়েছে। নিচের বাটনে সাবমিট করুন।", reply_markup=submit_markup())
            return
        req = reqs[idx]
        if req["kind"] != kind:
            need = "📸 ছবি (স্ক্রিনশট)" if req["kind"] == "photo" else "✍️ লিখিত উত্তর"
            await ask_proof_step(message, idx, reqs, prefix=f"⚠️ <b>এই ধাপে {need} দিতে হবে!</b>\n\n")
            return
        if kind == "text" and not text_value:
            await ask_proof_step(message, idx, reqs, prefix="⚠️ <b>উত্তর খালি রাখা যাবে না।</b>\n\n")
            return
        answers = list(data.get("answers", []))
        answers.append({"requirement_id": int(req.get("id") or 0), "prompt": req["prompt"], "kind": kind, "text_value": text_value, "file_id": file_id})
        idx += 1
        await state.update_data(answers=answers, req_index=idx)
        save_proof_draft(uid, await state.get_data())
    if idx < len(reqs):
        await ask_proof_step(message, idx, reqs, prefix=f"✅ ধাপ {idx}/{len(reqs)} নেওয়া হয়েছে।\n\n")
    else:
        await message.answer(f"🎉 সব {len(reqs)}টি ধাপ সম্পন্ন হয়েছে। এখন সাবমিট করুন।", reply_markup=submit_markup())


@dp.message(ProofFSM.photos, F.photo)
async def proof_photos(message: Message, state: FSMContext) -> None:
    # Telegram-এর সাধারণ ছবি (photo) হিসেবে পাঠানো প্রমাণ
    try:
        if not message.photo:
            await message.answer("⚠️ ছবিটি পাওয়া যায়নি। আবার ছবি পাঠান।")
            return
        await save_task_answer(message, state, "photo", file_id=message.photo[-1].file_id)
    except Exception as exc:
        print(f"[PROOF PHOTO ERROR] user={message.from_user.id if message.from_user else 0}: {exc}")
        await message.answer("⚠️ ছবিটি গ্রহণ করা যায়নি। অনুগ্রহ করে ছবিটি আবার সাধারণ <b>Photo</b> হিসেবে (File/Document নয়) পাঠান।")


@dp.message(ProofFSM.photos, F.text)
async def proof_text_answer(message: Message, state: FSMContext) -> None:
    await save_task_answer(message, state, "text", text_value=message.text.strip()[:1000])


@dp.message(ProofFSM.photos)
async def proof_wrong_type(message: Message, state: FSMContext) -> None:
    data = await state.get_data(); reqs = data.get("reqs", []); idx = int(data.get("req_index", 0))
    if reqs and idx < len(reqs):
        await ask_proof_step(message, idx, reqs, prefix="⚠️ <b>শুধু ছবি (Photo) বা লেখা পাঠাতে পারবেন — ফাইল/ভিডিও/স্টিকার নয়।</b>\n\n")
    else:
        await message.answer("⚠️ শুধু ছবি (Photo) বা লেখা পাঠান।")


@dp.callback_query(F.data == "proofback")
async def cb_proof_back(call: CallbackQuery, state: FSMContext) -> None:
    uid = call.from_user.id
    async with proof_lock(uid):
        data = await ensure_proof_state(uid, state)
        answers = list(data.get("answers", [])); reqs = data.get("reqs", [])
        if not reqs:
            await call.answer("⚠️ সেশন পাওয়া যায়নি, কাজ থেকে আবার শুরু করুন।", show_alert=True); return
        if not answers:
            await call.answer("এটাই প্রথম ধাপ।", show_alert=True); return
        answers.pop(); idx = len(answers)
        await state.update_data(answers=answers, req_index=idx)
        save_proof_draft(uid, await state.get_data())
    await ask_proof_step(call.message, idx, reqs, prefix="↩️ আগের উত্তরটি বাদ দেওয়া হয়েছে। আবার দিন।\n\n")
    await call.answer()


@dp.callback_query(F.data == "proofresume")
async def cb_proof_resume(call: CallbackQuery, state: FSMContext) -> None:
    data = await ensure_proof_state(call.from_user.id, state)
    reqs = data.get("reqs", []); idx = int(data.get("req_index", 0))
    if not reqs:
        await call.answer("⚠️ অসমাপ্ত প্রমাণ পাওয়া যায়নি।", show_alert=True); return
    if idx >= len(reqs):
        await call.message.answer("✅ সব ধাপ সম্পন্ন। সাবমিট করুন।", reply_markup=submit_markup())
    else:
        await ask_proof_step(call.message, idx, reqs, prefix="▶️ আগের জায়গা থেকে চালিয়ে যান।\n\n")
    await call.answer()


@dp.callback_query(F.data == "proofcancel")
async def cb_proof_cancel(call: CallbackQuery, state: FSMContext) -> None:
    await state.clear(); clear_proof_draft(call.from_user.id)
    await call.message.answer("❌ প্রমাণ জমা বাতিল করা হয়েছে।", reply_markup=main_menu(call.from_user.id)); await call.answer()


@dp.callback_query(F.data == "proofdone")
async def cb_proof_done(call: CallbackQuery, state: FSMContext) -> None:
    tg_id = call.from_user.id
    async with proof_lock(tg_id):
        data = await ensure_proof_state(tg_id, state)
        answers = list(data.get("answers", [])); reqs = data.get("reqs", [])
        task_id = int(data.get("task_id", 0))
        if data.get("submitting"):
            await call.answer("⏳ জমা হচ্ছে, অপেক্ষা করুন...", show_alert=False); return
        if not reqs or len(answers) != len(reqs):
            await call.answer("⚠️ প্রতিটি ধাপের উত্তর দিতে হবে! সেশন না পেলে কাজ থেকে আবার শুরু করুন।", show_alert=True); return
        await state.update_data(submitting=True)
    task = q("SELECT * FROM tasks WHERE id=?", (task_id,), one=True)
    if not task:
        await state.clear(); await call.answer("❌ কাজটি পাওয়া যায়নি", show_alert=True); return
    existing = q("SELECT id, status FROM task_done WHERE task_id=? AND user_id=?", (task_id, tg_id), one=True)
    if existing and existing["status"] != "rejected":
        await state.clear(); await call.answer("⚠️ এই কাজটি আগেই জমা দিয়েছেন!", show_alert=True); return
    if int(task["slots"]) - int(task["done"]) <= 0:
        await state.clear(); await call.answer("😔 স্লট শেষ হয়ে গেছে", show_alert=True); return
    if existing and existing["status"] == "rejected":
        done_id = int(existing["id"])
        q("DELETE FROM task_answers WHERE done_id=?", (done_id,))
        q("DELETE FROM proofs WHERE done_id=?", (done_id,))
        q("UPDATE task_done SET status='pending', note='', submitted_at=?, decided_at=NULL, decided_by=0 WHERE id=?", (now(), done_id))
    else:
        done_id = insert_id("INSERT INTO task_done(task_id, user_id, status, submitted_at) VALUES(?,?, 'pending', ?)", (task_id, tg_id, now()))
    for ans in answers:
        q("INSERT INTO task_answers(done_id, requirement_id, prompt, kind, text_value, file_id, created_at) VALUES(?,?,?,?,?,?,?)", (done_id, ans["requirement_id"], ans["prompt"], ans["kind"], ans["text_value"], ans["file_id"], now()))
        if ans["file_id"]:
            q("INSERT INTO proofs(done_id, file_id, created_at) VALUES(?,?,?)", (done_id, ans["file_id"], now()))
    q("UPDATE tasks SET done=done+1 WHERE id=?", (task_id,)); await state.clear(); clear_proof_draft(tg_id)
    await call.message.answer(f"{DIV}\n✅ <b>প্রমাণ জমা সম্পন্ন!</b>\n{DIV}\n\n🎯 কাজ: <b>{esc(task['title'])}</b>\n🧾 প্রমাণ: {len(answers)}টি\n📌 স্ট্যাটাস: ⏳ পেন্ডিং", reply_markup=main_menu(tg_id))
    text_answers = "\n".join(f"✍️ {esc(a['prompt'])}: <code>{esc(a['text_value'])}</code>" for a in answers if a["kind"] == "text")
    admin_text = (f"{DIV}\n🔔 <b>নতুন কাজের প্রমাণ জমা!</b>\n{DIV}\n\n🆔 সাবমিশন: #{done_id}\n🎯 কাজ: <b>{esc(task['title'])}</b>\n👤 ইউজার: {user_label(get_user(tg_id))}\n🆔 ইউজার আইডি: <code>{tg_id}</code>\n📌 প্রমাণের ধাপ: {len(answers)}টি" + ("\n\n" + text_answers if text_answers else ""))
    photos = [a["file_id"] for a in answers if a.get("file_id")]
    await notify_admins_action(admin_text, kb([b("✅ এপ্রুভ", f"pok:{done_id}"), b("❌ রিজেক্ট", f"pno:{done_id}")], [b("🔍 বিস্তারিত দেখুন", f"pview:{done_id}")]), photos)
    await call.answer("✅ জমা সম্পন্ন!")


# ══════════════════════════ ব্যালেন্স প্যানেল ══════════════════════════
async def balance_panel(tg_id: int, message: Message) -> None:
    user = get_user(tg_id)
    if not user:
        ensure_user(message)
        user = get_user(tg_id)
    dep = q("SELECT COUNT(*) AS c FROM deposits WHERE user_id=? AND status='approved'", (tg_id,), one=True)["c"]
    wd = q("SELECT COUNT(*) AS c FROM withdrawals WHERE user_id=? AND status IN ('pending','approved')", (tg_id,), one=True)["c"]
    text = (
        f"{DIV}\n💰 <b>আপনার ব্যালেন্স</b>\n{DIV}\n\n"
        + box(
            [
                f"👛 <b>বর্তমান ব্যালেন্স</b>: {taka(user['balance'])}",
                f"💎 <b>মোট আয়</b>: {taka(user['total_earn'])}",
                f"📥 <b>মোট ডিপোজিট</b>: {taka(user['total_deposit'])} ({dep} বার)",
                f"📤 <b>মোট উইথড্র</b>: {taka(user['total_withdraw'])} ({wd} বার)",
                f"👥 <b>রেফার বোনাস</b>: {int(user['refer_count'])} জন",
            ],
            "হিসাব",
            "💰",
        )
        + "\n\nℹ️ <b>নোট</b>: ইউজার ও এজেন্ট — সবার ব্যালেন্স একই সিস্টেমে থাকে।"
    )
    text = custom_reply("bal", tg_id) or text
    rows = [
        [b("📥 ডিপোজিট করুন", "dep", GREEN), b("📤 টাকা তুলুন", "wd", RED)],
        [b("🧾 লেনদেন হিস্টোরি", "txn", BLUE), b("📋 আইডি কপি", "cpid", BLUE)],
        [back_btn()],
    ]
    try:
        if isinstance(message, CallbackQuery):
            await message.message.edit_text(text, reply_markup=kb(*rows))
        else:
            await message.answer(text, reply_markup=kb(*rows))
    except TelegramBadRequest:
        await message.answer(text, reply_markup=kb(*rows))


@dp.callback_query(F.data == "bal")
async def cb_bal(call: CallbackQuery) -> None:
    await balance_panel(call.from_user.id, call.message)
    await call.answer()


# ═════════════════ 🔐 অটো USDT (BEP20 / BSC) ডিপোজিট ও উইথড্র ═════════════════
# Private Key শুধু environment (.env) থেকে আসে — কোডে বা লগে কখনো ছাপা হয় না।
import threading
from decimal import Decimal, ROUND_DOWN, ROUND_UP, InvalidOperation

try:
    from web3 import Web3
    from eth_account import Account
    _WEB3_IMPORT_ERROR = ""
except Exception as _exc:  # web3 ইনস্টল না থাকলে বাকি বট চালু থাকবে, শুধু অটো-পেমেন্ট বন্ধ থাকবে
    Web3 = None
    Account = None
    _WEB3_IMPORT_ERROR = type(_exc).__name__

_ERC20_ABI = [
    {"constant": True, "inputs": [{"name": "_owner", "type": "address"}], "name": "balanceOf",
     "outputs": [{"name": "balance", "type": "uint256"}], "type": "function"},
    {"constant": False, "inputs": [{"name": "_to", "type": "address"}, {"name": "_value", "type": "uint256"}],
     "name": "transfer", "outputs": [{"name": "", "type": "bool"}], "type": "function"},
]
_TRANSFER_TOPIC = "0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef"
MIN_GAS_WEI = 10 ** 15  # 0.001 BNB — এর কম থাকলে অটো উইথড্র পাঠানো হবে না

_w3 = None
_account = None
_wallet = ""
_crypto_error = "PRIVATE_KEY সেট করা নেই"
_chain_lock = threading.Lock()
_async_locks: dict = {}
_last_lowbal_alert = 0.0
_RECOVERED_PROCESSING = 0


def _alock(name: str) -> asyncio.Lock:
    if name not in _async_locks:
        _async_locks[name] = asyncio.Lock()
    return _async_locks[name]


def init_crypto() -> bool:
    """env থেকে PRIVATE_KEY পড়ে ওয়ালেট ও BSC RPC প্রস্তুত করে।"""
    global _w3, _account, _wallet, _crypto_error
    _w3 = None
    _account = None
    _wallet = ""
    if Web3 is None:
        _crypto_error = f"web3 লাইব্রেরি নেই — চালান: pip install web3 ({_WEB3_IMPORT_ERROR})"
        return False
    key = PRIVATE_KEY
    if not key:
        _crypto_error = "PRIVATE_KEY সেট করা নেই"
        return False
    if not key.lower().startswith("0x"):
        key = "0x" + key
    if not re.fullmatch(r"0x[0-9a-fA-F]{64}", key):
        _crypto_error = "PRIVATE_KEY ফরম্যাট ভুল (0x + ৬৪ হেক্স = ৬৬ অক্ষর হতে হবে)"
        return False
    try:
        _account = Account.from_key(key)
        _wallet = _account.address
        _w3 = Web3(Web3.HTTPProvider(BSC_RPC, request_kwargs={"timeout": 25}))
    except Exception as exc:
        _w3 = None
        _account = None
        _wallet = ""
        _crypto_error = f"ওয়ালেট লোড হয়নি ({type(exc).__name__})"
        return False
    _crypto_error = ""
    return True


def crypto_ready() -> bool:
    return bool(_w3 is not None and _account is not None and _wallet)


def crypto_status_line() -> str:
    if crypto_ready():
        return f"💠 অটো USDT (BEP20): চালু • ওয়ালেট {_wallet}"
    return f"💠 অটো USDT (BEP20): বন্ধ — {_crypto_error}"


def crypto_db_guard() -> int:
    global _RECOVERED_PROCESSING
    """একই TxID দুইবার ক্রেডিট ঠেকাতে ইউনিক ইনডেক্স; অসমাপ্ত অটো-উইথড্র পেন্ডিং-এ ফেরত।"""
    try:
        q("CREATE UNIQUE INDEX IF NOT EXISTS idx_auto_usdt_deposit_tx ON deposits(trx_id) WHERE method='usdt_bsc'")
    except Exception as exc:
        print("auto deposit index error:", type(exc).__name__)
    try:
        rows = q("SELECT id FROM withdrawals WHERE method='usdt_bsc' AND status='processing'")
        if rows:
            q(
                "UPDATE withdrawals SET status='pending', note=? WHERE method='usdt_bsc' AND status='processing'",
                ("সার্ভার রিস্টার্টে অটো-পেমেন্ট মাঝপথে থেমেছে — অন-চেইনে চেক করে এপ্রুভ/রিজেক্ট করুন",),
            )
        _RECOVERED_PROCESSING = len(rows)
        return _RECOVERED_PROCESSING
    except Exception as exc:
        print("auto withdraw recovery error:", type(exc).__name__)
        return 0


