def is_valid_bsc_address(addr: str) -> bool:
    if Web3 is None or not isinstance(addr, str):
        return False
    addr = addr.strip()
    if not re.fullmatch(r"0x[0-9a-fA-F]{40}", addr):
        return False
    if int(addr, 16) == 0:
        return False
    try:
        if not Web3.is_address(addr):
            return False
        return Web3.to_checksum_address(addr).lower() != _wallet.lower()
    except Exception:
        return False


def _hx(v) -> str:
    if isinstance(v, (bytes, bytearray)):
        return "0x" + bytes(v).hex()
    s = v.hex() if hasattr(v, "hex") else str(v)
    return s if s.startswith("0x") else "0x" + s


def _usdt_contract():
    return _w3.eth.contract(address=Web3.to_checksum_address(USDT_BSC_CONTRACT), abi=_ERC20_ABI)


def _wallet_balances_sync():
    usdt_raw = int(_usdt_contract().functions.balanceOf(_wallet).call())
    bnb_raw = int(_w3.eth.get_balance(_wallet))
    return usdt_raw, bnb_raw, int(_w3.eth.gas_price)


# ───────────────────────── অটো ডিপোজিট: TxID যাচাই ─────────────────────────
async def _scan_call(action: str, **extra):
    import aiohttp
    params = {"chainid": "56", "module": "proxy", "action": action, "apikey": BSCSCAN_API_KEY}
    params.update(extra)
    async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=20)) as session:
        async with session.get(BSCSCAN_API_URL, params=params) as resp:
            data = await resp.json(content_type=None)
    if not isinstance(data, dict):
        raise RuntimeError("BscScan: অস্বাভাবিক রেসপন্স")
    res = data.get("result")
    if isinstance(res, str) and not res.startswith("0x"):
        raise RuntimeError(f"BscScan: {res[:100]}")
    return res


def _norm_receipt_scan(r: dict) -> dict:
    st = r.get("status")
    status = int(st, 16) if isinstance(st, str) else int(st or 0)
    return {
        "status": status,
        "block": int(r["blockNumber"], 16),
        "logs": [
            {"address": str(lg["address"]), "topics": [str(t) for t in lg.get("topics", [])], "data": str(lg.get("data", "0x"))}
            for lg in r.get("logs", [])
        ],
    }


def _norm_receipt_rpc(r) -> dict:
    return {
        "status": int(r["status"]),
        "block": int(r["blockNumber"]),
        "logs": [
            {"address": str(lg["address"]), "topics": [_hx(t) for t in lg["topics"]], "data": _hx(lg["data"])}
            for lg in r["logs"]
        ],
    }


async def fetch_tx_receipt(txhash: str):
    """(receipt|None, latest_block) — প্রথমে BscScan API, ব্যর্থ হলে BSC RPC।"""
    if BSCSCAN_API_KEY:
        try:
            r = await _scan_call("eth_getTransactionReceipt", txhash=txhash)
            if r:
                latest = int(await _scan_call("eth_blockNumber"), 16)
                return _norm_receipt_scan(r), latest
        except Exception as exc:
            print("BscScan error:", type(exc).__name__, str(exc)[:120] if isinstance(exc, RuntimeError) else "")

    def _rpc():
        try:
            r = _w3.eth.get_transaction_receipt(txhash)
        except Exception as exc:
            if type(exc).__name__ == "TransactionNotFound":
                return None, 0
            raise
        return _norm_receipt_rpc(r), int(_w3.eth.block_number)

    return await asyncio.to_thread(_rpc)


def parse_usdt_received(receipt: dict):
    """রিসিপ্ট থেকে আমার ওয়ালেটে আসা আসল USDT (BEP20) এর মোট পরিমাণ ও প্রেরকের ঠিকানা।"""
    me = _wallet.lower()
    token = USDT_BSC_CONTRACT.lower()
    total_raw = 0
    sender = ""
    for lg in receipt["logs"]:
        topics = lg["topics"]
        if lg["address"].lower() != token or len(topics) < 3 or topics[0].lower() != _TRANSFER_TOPIC:
            continue
        if ("0x" + topics[2][-40:]).lower() != me:
            continue
        total_raw += int(lg["data"], 16)
        sender = "0x" + topics[1][-40:]
    return total_raw / (10 ** USDT_DECIMALS), sender


