@dp.message(DepositFSM.autotx, F.text)
async def dep_auto_txid(message: Message, state: FSMContext) -> None:
    tg_id = message.from_user.id
    txid = (message.text or "").strip()
    if not re.fullmatch(r"0x[0-9a-fA-F]{64}", txid):
        await message.answer("⚠️ <b>TxID সঠিক নয়!</b>\nTxID অবশ্যই <code>0x</code> দিয়ে শুরু হয়ে মোট ৬৬ অক্ষরের হবে। আবার পাঠান।")
        return
    txid = txid.lower()
    data = await state.get_data()
    method = data.get("method", "usdt_bsc")
    if method not in PAYMENT_METHODS or not payment_method_enabled(method):
        await state.clear()
        await message.answer("⛔ অটো ডিপোজিট এখন বন্ধ আছে।", reply_markup=main_menu(tg_id))
        return

    wait_msg = await message.answer("🔎 <b>ব্লকচেইনে TxID যাচাই করা হচ্ছে…</b>")
    async with _alock("deposit"):
        dup = q("SELECT id FROM deposits WHERE method=? AND lower(trx_id)=?", (method, txid), one=True)
        if dup:
            await state.clear()
            await message.answer("⚠️ <b>এই TxID আগেই ব্যবহার করা হয়েছে!</b>", reply_markup=main_menu(tg_id))
            return
        try:
            receipt, latest = await fetch_tx_receipt(txid)
        except Exception as exc:
            print("deposit verify error:", type(exc).__name__)
            await message.answer("⚠️ ব্লকচেইন সার্ভারে সাময়িক সমস্যা। ১-২ মিনিট পর আবার TxID পাঠান।")
            return
        if receipt is None:
            await message.answer(
                "⏳ <b>TxID পাওয়া যায়নি বা ট্রান্সফার এখনো কনফার্ম হয়নি।</b>\n"
                "TxID ঠিক আছে কিনা দেখে ১-২ মিনিট পর আবার পাঠান।"
            )
            return
        if receipt["status"] != 1:
            await state.clear()
            await message.answer("❌ এই ট্রান্সফারটি ব্লকচেইনে <b>ব্যর্থ (failed)</b> হয়েছে। কোনো টাকা যোগ হয়নি।", reply_markup=main_menu(tg_id))
            return
        usdt_amount, sender = parse_usdt_received(receipt)
        if usdt_amount <= 0:
            await state.clear()
            await message.answer(
                "❌ <b>এই ট্রান্সফারে আমাদের অ্যাড্রেসে USDT (BEP20) আসেনি।</b>\n"
                "সঠিক অ্যাড্রেস ও নেটওয়ার্ক (BSC) ব্যবহার করেছেন কিনা চেক করুন।",
                reply_markup=main_menu(tg_id),
            )
            return
        confirmations = latest - receipt["block"] + 1
        if confirmations < MIN_CONFIRMATIONS:
            await message.answer(
                f"⏳ <b>কনফার্মেশন বাকি ({max(confirmations, 0)}/{MIN_CONFIRMATIONS})</b>\n"
                "প্রায় ৩০ সেকেন্ড পর একই TxID আবার পাঠান।"
            )
            return
        credit = round(usdt_amount * setting_float("usdt_rate", 122), 2)
        conn = connect()
        try:
            conn.execute(
                "INSERT INTO deposits(user_id, method, amount, credit, trx_id, sender_number, file_ids, status, note, created_at, decided_at) "
                "VALUES(?,?,?,?,?,?, '', 'approved', 'Auto BSC USDT', ?, ?)",
                (tg_id, method, round(usdt_amount, 6), credit, txid, sender, now(), now()),
            )
            dep_id = int(conn.execute("SELECT last_insert_rowid()").fetchone()[0])
            conn.execute("UPDATE users SET balance = balance + ?, total_deposit = total_deposit + ? WHERE id=?", (credit, credit, tg_id))
            conn.commit()
        except sqlite3.IntegrityError:
            conn.rollback()
            await state.clear()
            await message.answer("⚠️ <b>এই TxID আগেই ব্যবহার করা হয়েছে!</b>", reply_markup=main_menu(tg_id))
            return
        finally:
            conn.close()

    await state.clear()
    log_txn(tg_id, "deposit", credit, f"অটো ডিপোজিট #{dep_id} • USDT BEP20 • {usdt_amount:.4f} USDT")
    try:
        await post_proof_payment("deposit", credit, method, tg_id)
    except Exception as exc:
        print("proof post error:", type(exc).__name__)
    await message.answer(
        f"{DIV}\n🎉 <b>ডিপোজিট সফল হয়েছে!</b>\n{DIV}\n\n"
        + box(
            [
                f"🆔 <b>ডিপোজিট আইডি</b>: #{dep_id}",
                f"🪙 <b>যোগ হয়েছে</b>: {usdt_text(usdt_amount)}",
                f"👛 <b>নতুন ব্যালেন্স</b>: {money(method, get_balance(tg_id))}",
                f"🔗 <a href=\"https://bscscan.com/tx/{txid}\">BscScan-এ দেখুন</a>",
            ],
            "অটো ডিপোজিট",
            "📥",
        ),
        reply_markup=main_menu(tg_id),
    )
    await notify_admins(
        f"{DIV}\n📥 <b>অটো ডিপোজিট (USDT BEP20)</b>\n{DIV}\n\n"
        + box(
            [
                f"🆔 #{dep_id}",
                f"👤 {user_label(get_user(tg_id))} • <code>{tg_id}</code>",
                f"🪙 {usdt_amount:.4f} USDT → {taka(credit)}",
                f"🔗 <code>{txid}</code>",
            ],
            "অটো এপ্রুভড",
            "✅",
        )
    )


# ───────────────────────── অটো উইথড্র: ওয়ালেট থেকে সরাসরি পাঠানো ─────────────────────────
class _NotSent(Exception):
    """ট্রান্সফার ব্রডকাস্টই হয়নি — ব্যালেন্স ফেরত দেওয়া নিরাপদ।"""


def _send_usdt_sync(to_address: str, raw_amount: int):
    """(txhash, uncertain). Nonce race ঠেকাতে থ্রেড-লক ব্যবহার হয়।"""
    with _chain_lock:
        try:
            to = Web3.to_checksum_address(to_address)
            fn = _usdt_contract().functions.transfer(to, int(raw_amount))
            nonce = _w3.eth.get_transaction_count(_wallet, "pending")
            gas = int(fn.estimate_gas({"from": _wallet}) * 1.25)
            tx = fn.build_transaction(
                {"from": _wallet, "nonce": nonce, "gas": gas, "gasPrice": int(_w3.eth.gas_price), "chainId": 56}
            )
            signed = _account.sign_transaction(tx)
            raw_tx = getattr(signed, "raw_transaction", None) or signed.rawTransaction
            local_hash = _hx(signed.hash)
        except Exception as exc:
            raise _NotSent(f"{type(exc).__name__}: {str(exc)[:150]}")
        try:
            return _hx(_w3.eth.send_raw_transaction(raw_tx)), False
        except Exception as exc:
            network_issue = "requests" in type(exc).__module__ or isinstance(exc, (ConnectionError, TimeoutError, OSError))
            if not network_issue:
                raise _NotSent(f"{type(exc).__name__}: {str(exc)[:150]}")
            time.sleep(3)
            try:
                _w3.eth.get_transaction(local_hash)
                return local_hash, False
            except Exception:
                return local_hash, True


def _wait_receipt_sync(txhash: str, timeout: int = 150):
    try:
        r = _w3.eth.wait_for_transaction_receipt(txhash, timeout=timeout, poll_latency=2)
        return int(r["status"])
    except Exception:
        return None


def _wd_refund(wd_id: int, uid: int, amount: float, note: str) -> bool:
    conn = connect()
    try:
        cur = conn.execute(
            "UPDATE withdrawals SET status='rejected', decided_at=?, note=? WHERE id=? AND status='processing'",
            (now(), note[:200], wd_id),
        )
        if cur.rowcount != 1:
            conn.rollback()
            return False
        conn.execute("UPDATE users SET balance = balance + ? WHERE id=?", (float(amount), uid))
        conn.commit()
        return True
    finally:
        conn.close()


def _wd_mark_paid(wd_id: int, uid: int, amount: float, txh: str) -> bool:
    conn = connect()
    try:
        cur = conn.execute(
            "UPDATE withdrawals SET status='approved', decided_at=?, note=? WHERE id=? AND status IN ('processing','pending')",
            (now(), f"Auto • {txh}", wd_id),
        )
        if cur.rowcount != 1:
            conn.rollback()
            return False
        conn.execute("UPDATE users SET total_withdraw = total_withdraw + ? WHERE id=?", (float(amount), uid))
        conn.commit()
        return True
    finally:
        conn.close()


def _wd_to_pending(wd_id: int, note: str) -> None:
    q("UPDATE withdrawals SET status='pending', note=? WHERE id=? AND status='processing'", (note[:200], wd_id))


