async def auto_withdraw_request(message: Message, state: FSMContext, data: dict, amount: float) -> None:
    global _last_lowbal_alert
    tg_id = message.from_user.id
    method = data["method"]
    m = PAYMENT_METHODS[method]
    address = data.get("account", "")
    rate = setting_float("usdt_rate", 122)
    if rate <= 0 or not is_valid_bsc_address(address):
        await state.clear()
        await message.answer("⚠️ অ্যাড্রেস বা রেট সঠিক নয়। আবার চেষ্টা করুন।", reply_markup=main_menu(tg_id))
        return
    usdt = (Decimal(str(amount)) / Decimal(str(rate))).quantize(Decimal("0.0001"), rounding=ROUND_DOWN)
    if usdt <= 0:
        await message.answer("⚠️ এমাউন্ট খুব কম। আরও বেশি লিখুন।")
        return
    if usdt > Decimal(str(AUTO_WITHDRAW_MAX_USDT)):
        await message.answer(
            f"⚠️ অটো উইথড্রে একবারে সর্বোচ্চ {AUTO_WITHDRAW_MAX_USDT:g} USDT তোলা যায়। কম এমাউন্ট লিখুন।"
        )
        return
    raw_amount = int(usdt * (10 ** USDT_DECIMALS))
    address = Web3.to_checksum_address(address)

    txh = ""
    uncertain = False
    wd_id = 0
    async with _alock("withdraw"):
        try:
            usdt_bal, bnb_bal, gas_price = await asyncio.to_thread(_wallet_balances_sync)
        except Exception as exc:
            print("wallet balance error:", type(exc).__name__)
            await state.clear()
            await message.answer("⚠️ ব্লকচেইন সার্ভারে সাময়িক সমস্যা। একটু পরে আবার চেষ্টা করুন। আপনার ব্যালেন্স কাটা হয়নি।", reply_markup=main_menu(tg_id))
            return
        need_bnb = int(gas_price * 100000 * 2)  # ট্রান্সফারের আনুমানিক গ্যাস × ২ নিরাপত্তা
        short_usdt = usdt_bal < raw_amount
        short_bnb = bnb_bal < need_bnb
        if short_usdt or short_bnb:
            await state.clear()
            reason = []
            if short_usdt:
                reason.append(f"USDT কম: আছে {usdt_bal / 10 ** USDT_DECIMALS:.4f}, লাগবে {usdt}")
            if short_bnb:
                reason.append(f"BNB (গ্যাস) কম: আছে {bnb_bal / 10 ** 18:.6f}, লাগবে প্রায় {need_bnb / 10 ** 18:.6f}")
            print("auto withdraw blocked:", " | ".join(reason))
            await message.answer(
                "⚠️ <b>অটো উইথড্র সাময়িকভাবে সম্ভব হচ্ছে না।</b>\nএডমিনকে জানানো হয়েছে, একটু পরে চেষ্টা করুন। আপনার ব্যালেন্স কাটা হয়নি।"
                + (("\n\n🔧 <b>এডমিন তথ্য:</b>\n" + "\n".join(esc(r) for r in reason)) if is_admin(tg_id) else ""),
                reply_markup=main_menu(tg_id),
            )
            if time.time() - _last_lowbal_alert > 1800:
                _last_lowbal_alert = time.time()
                await notify_admins(
                    f"{DIV}\n⚠️ <b>হট-ওয়ালেটে ব্যালেন্স কম!</b>\n{DIV}\n\n"
                    + box(
                        [
                            f"🪙 USDT: {usdt_bal / 10 ** USDT_DECIMALS:.4f}",
                            f"⛽ BNB (গ্যাস): {bnb_bal / 10 ** 18:.6f}",
                            *[f"❗ {esc(r)}" for r in reason],
                            f"📬 <code>{esc(_wallet)}</code>",
                        ],
                        "অটো উইথড্র আটকে আছে",
                        "💠",
                    )
                    + "\n\nওয়ালেটে USDT ও গ্যাসের জন্য BNB পাঠান।"
                )
            return

        conn = connect()
        try:
            cur = conn.execute("UPDATE users SET balance = balance - ? WHERE id=? AND balance >= ?", (amount, tg_id, amount))
            if cur.rowcount != 1:
                conn.rollback()
                await state.clear()
                await message.answer("⚠️ ব্যালেন্স যথেষ্ট নেই।", reply_markup=main_menu(tg_id))
                return
            cur = conn.execute(
                "INSERT INTO withdrawals(user_id, method, amount, account_no, status, note, created_at) "
                "VALUES(?,?,?,?, 'processing', 'Auto BSC USDT প্রসেসিং', ?)",
                (tg_id, method, amount, address, now()),
            )
            wd_id = int(cur.lastrowid)
            conn.commit()
        finally:
            conn.close()
        await state.clear()
        await message.answer(
            f"🔄 <b>অটো উইথড্র প্রসেস হচ্ছে… #{wd_id}</b>\n🪙 {usdt_text(usdt)}\nএকটু অপেক্ষা করুন।"
        )
        try:
            txh, uncertain = await asyncio.to_thread(_send_usdt_sync, address, raw_amount)
        except _NotSent as exc:
            _wd_refund(wd_id, tg_id, amount, f"অটো পাঠানো যায়নি — রিফান্ড ({str(exc)[:80]})")
            await message.answer(
                f"❌ <b>উইথড্র ব্যর্থ হয়েছে।</b>\n🪙 {usdt_text(usdt)} আপনার ব্যালেন্সে ফেরত দেওয়া হয়েছে।\n👛 ব্যালেন্স: {money(method, get_balance(tg_id))}",
                reply_markup=main_menu(tg_id),
            )
            await notify_admins(f"⚠️ <b>অটো উইথড্র #{wd_id} ব্যর্থ</b> (রিফান্ড হয়েছে)\n<code>{esc(str(exc)[:200])}</code>")
            return
        except Exception as exc:
            _wd_to_pending(wd_id, f"অটো পাঠানো অনিশ্চিত ({type(exc).__name__})")
            await message.answer(f"⏳ উইথড্র #{wd_id} এডমিন যাচাই করছেন। শীঘ্রই আপডেট পাবেন।", reply_markup=main_menu(tg_id))
            await _alert_admin_wd(wd_id, tg_id, amount, address, f"অপ্রত্যাশিত এরর: {type(exc).__name__}")
            return

    if uncertain:
        _wd_to_pending(wd_id, f"নেটওয়ার্ক টাইমআউট — হ্যাশ {txh}")
        await message.answer(f"⏳ উইথড্র #{wd_id} এডমিন যাচাই করছেন। শীঘ্রই আপডেট পাবেন।", reply_markup=main_menu(tg_id))
        await _alert_admin_wd(wd_id, tg_id, amount, address, f"ব্রডকাস্ট নিশ্চিত নয়। সম্ভাব্য হ্যাশ: {txh}")
        return

    status = await asyncio.to_thread(_wait_receipt_sync, txh)
    if status == 1:
        _wd_mark_paid(wd_id, tg_id, amount, txh)
        log_txn(tg_id, "withdraw", -float(amount), f"অটো উইথড্র #{wd_id} • USDT BEP20 • {usdt} USDT • {address}")
        try:
            await post_proof_payment("withdraw", float(amount), method, tg_id)
        except Exception as exc:
            print("proof post error:", type(exc).__name__)
        await notify_user(
            tg_id,
            f"{DIV}\n💸 <b>উইথড্র সফল হয়েছে!</b>\n{DIV}\n\n"
            + box(
                [
                    f"🆔 #{wd_id}",
                    f"🪙 এমাউন্ট: {usdt_text(usdt)}",
                    f"📬 অ্যাড্রেস: <code>{esc(address)}</code>",
                    f"👛 ব্যালেন্স: {money(method, get_balance(tg_id))}",
                    f"🔗 <a href=\"https://bscscan.com/tx/{txh}\">BscScan-এ দেখুন</a>",
                ],
                "অটো পেমেন্ট সম্পন্ন",
                "✅",
            ),
            "💸 উইথড্র সফল",
        )
        await notify_admins(f"✅ <b>অটো উইথড্র #{wd_id}</b> সম্পন্ন • {taka(amount)} ≈ {usdt} USDT\n<code>{txh}</code>")
    elif status == 0:
        _wd_refund(wd_id, tg_id, amount, f"অন-চেইনে ব্যর্থ — রিফান্ড • {txh}")
        await notify_user(
            tg_id,
            f"❌ <b>উইথড্র #{wd_id} ব্লকচেইনে ব্যর্থ হয়েছে।</b>\n🪙 {usdt_text(usdt)} ব্যালেন্সে ফেরত দেওয়া হয়েছে।",
            "❌ উইথড্র ব্যর্থ",
        )
        await notify_admins(f"⚠️ <b>অটো উইথড্র #{wd_id} অন-চেইনে ব্যর্থ</b> (রিফান্ড হয়েছে)\n<code>{txh}</code>")
    else:
        _wd_to_pending(wd_id, f"কনফার্মেশন টাইমআউট — হ্যাশ {txh}")
        await notify_user(tg_id, f"⏳ উইথড্র #{wd_id} ব্লকচেইনে প্রসেস হচ্ছে। শীঘ্রই আপডেট পাবেন।", "⏳ উইথড্র প্রসেসিং")
        await _alert_admin_wd(wd_id, tg_id, amount, address, f"কনফার্মেশন পাওয়া যায়নি। হ্যাশ: {txh}")



# ═════════════ USDT ডিসপ্লে হেল্পার (ভেতরে ব্যালেন্স ৳ টাকাতেই থাকে, শুধু দেখানোর সময় USDT) ═════════════
import math


def usdt_rate_now() -> Decimal:
    rate = setting_float("usdt_rate", 122)
    return Decimal(str(rate)) if rate > 0 else Decimal("122")


def taka_to_usdt(amount) -> Decimal:
    """টাকা → USDT (৪ ঘর, নিচের দিকে)।"""
    try:
        value = Decimal(str(round(float(amount), 2)))
    except (TypeError, ValueError, InvalidOperation):
        value = Decimal("0")
    return (value / usdt_rate_now()).quantize(Decimal("0.0001"), rounding=ROUND_DOWN)


def usdt_to_taka(usdt) -> Decimal:
    """USDT → টাকা (২ ঘর, উপরের দিকে — যাতে উইথড্রে USDT কম না পড়ে)।"""
    return (Decimal(str(usdt)) * usdt_rate_now()).quantize(Decimal("0.01"), rounding=ROUND_UP)


def usdt_min_up(taka_amount) -> Decimal:
    """টাকার মিনিমামের সমান USDT (৪ ঘর, উপরের দিকে)।"""
    return (Decimal(str(taka_amount)) / usdt_rate_now()).quantize(Decimal("0.0001"), rounding=ROUND_UP)


def usdt_text(value) -> str:
    try:
        return f"{Decimal(str(value)):,.4f} USDT"
    except (InvalidOperation, ValueError):
        return "0.0000 USDT"


def is_auto_method(method: str) -> bool:
    return PAYMENT_METHODS.get(method, {}).get("type") == "auto"


def money(method: str, taka_amount) -> str:
    """ইউজারকে দেখানোর জন্য: USDT মেথডে USDT, বাকি মেথডে ৳ টাকা।"""
    if is_auto_method(method):
        return usdt_text(taka_to_usdt(taka_amount))
    return taka(taka_amount)


def wd_min_text(method: str) -> str:
    minimum = setting_float("min_withdraw", 100)
    return usdt_text(usdt_min_up(minimum)) if is_auto_method(method) else taka(minimum)


