# ══════════════════════════ এজেন্ট প্যানেল ══════════════════════════
async def agent_panel(tg_id: int, message: Message) -> None:
    user = get_user(tg_id)
    tasks = q("SELECT * FROM tasks WHERE created_by=? ORDER BY id DESC LIMIT 50", (tg_id,))
    total_slots = sum(int(t["slots"]) for t in tasks)
    total_done = sum(int(t["done"]) for t in tasks)
    total_cost = sum(float(t["reward"]) * int(t["slots"]) for t in tasks)
    text = (
        f"{DIV}\n🤝 <b>এজেন্ট প্যানেল</b>\n{DIV}\n\n"
        + box(
            [
                f"👛 <b>এজেন্ট ব্যালেন্স</b>: {taka(user['balance'])}",
                f"📦 <b>মোট কাজ দিয়েছেন</b>: {len(tasks)} টি",
                f"🎯 <b>মোট স্লট</b>: {total_slots} টি",
                f"✅ <b>সম্পন্ন</b>: {total_done} টি",
                f"💸 <b>মোট খরচ</b>: {taka(total_cost)}",
            ],
            "এজেন্ট স্ট্যাটাস",
            "🤝",
        )
        + "\n\n👇 <b>নিচের বাটন থেকে বেছে নিন</b>"
    )
    text = custom_reply("agent", tg_id) or text
    agent_keyboard = ReplyKeyboardMarkup(
        keyboard=[
            [rkb(B_AGENT_NEW, GREEN), rkb(B_AGENT_MY, BLUE)],
            [rkb(B_AGENT_PROOFS, BLUE), rkb(B_AGENT_DEPOSIT, GREEN)],
            [rkb(B_AGENT_BAL, GREEN), rkb("🏠 মেইন মেনু", RED)],
        ], resize_keyboard=True, input_field_placeholder="এজেন্ট প্যানেলের বাটন বেছে নিন"
    )
    if isinstance(message, CallbackQuery):
        try:
            await message.message.edit_text(text)
            await message.message.answer("👇 এজেন্ট প্যানেলের কিবোর্ড বাটন ব্যবহার করুন।", reply_markup=agent_keyboard)
        except TelegramBadRequest:
            await message.message.answer(text, reply_markup=agent_keyboard)
    else:
        await message.answer(text, reply_markup=agent_keyboard)


