@dp.callback_query(F.data.startswith("uic:"))
async def cb_ui_config_edit(call: CallbackQuery, state: FSMContext):
    if not admin_only(call):
        await call.answer("⛔", show_alert=True); return
    key = call.data.split(":", 1)[1]
    allowed = set(UI_DEFAULTS) - {"update_photo", "proof_photo"}
    if key not in allowed:
        await call.answer("Invalid setting", show_alert=True); return
    prompts = {
        "update_channel_id":"Update Channel-এর numeric ID দিন (যেমন -1001234567890)।",
        "proof_channel_id":"Payment Proof Channel-এর numeric ID দিন।",
        "join_log_channel_id":"Join Log Channel-এর numeric ID দিন।",
        "update_url":"Update পোস্টের URL দিন (https://... বা https://t.me/...)।",
        "proof_url":"Payment Proof পোস্টের URL দিন।",
        "update_button_text":"Update URL বাটনের নতুন লেখা দিন।",
        "proof_button_text":"Payment Proof URL বাটনের নতুন লেখা দিন।",
        "update_button_color":"কালার লিখুন: success (সবুজ), primary (নীল), danger (লাল)।",
        "proof_button_color":"কালার লিখুন: success (সবুজ), primary (নীল), danger (লাল)।",
    }
    await state.set_state(AdminFSM.ui_value); await state.update_data(ui_key=key)
    await call.message.answer(prompts[key] + "\n/cancel লিখলে বাতিল হবে।")
    await call.answer()

