@dp.message(AdminFSM.ui_value, F.text)
async def msg_ui_config_value(message: Message, state: FSMContext):
    if not is_admin(message.from_user.id): await state.clear(); return
    value = (message.text or "").strip()
    if value.lower() == "/cancel": await state.clear(); await message.answer("বাতিল হয়েছে।"); return
    data = await state.get_data(); key = data.get("ui_key")
    cfg = load_ui_config()
    if key in ("update_channel_id", "proof_channel_id", "join_log_channel_id"):
        try: value = int(value)
        except ValueError: await message.answer("❌ numeric channel ID দিন, যেমন -1001234567890"); return
    elif key in ("update_url", "proof_url"):
        if not value.startswith(("https://", "http://")): await message.answer("❌ URL অবশ্যই http:// বা https:// দিয়ে শুরু হবে।"); return
    elif key in ("update_button_color", "proof_button_color"):
        value = value.lower()
        if value not in ("success", "primary", "danger"): await message.answer("❌ success, primary অথবা danger দিন।"); return
    if key not in UI_DEFAULTS: await state.clear(); return
    cfg[key] = value; save_ui_config(cfg); await state.clear()
    await message.answer("✅ সেটিংস সেভ হয়েছে।", reply_markup=kb([b("⚙️ Channel UI Settings", "ui_settings", BLUE), back_btn("admin")]))

@dp.message(AdminFSM.ui_photo, F.photo)
async def msg_ui_config_photo(message: Message, state: FSMContext):
    if not is_admin(message.from_user.id): await state.clear(); return
    data = await state.get_data(); key = data.get("ui_key")
    cfg = load_ui_config()
    if key not in ("update_photo", "proof_photo"): await state.clear(); return
    cfg[key] = message.photo[-1].file_id; save_ui_config(cfg); await state.clear()
    await message.answer("✅ ছবি সেভ হয়েছে।", reply_markup=kb([b("⚙️ Channel UI Settings", "ui_settings", BLUE), back_btn("admin")]))

