@dp.callback_query(F.data.startswith("wno:"))
async def cb_wno(call: CallbackQuery) -> None:
    if not admin_only(call):
        await call.answer("⛔", show_alert=True)
        return
    wid = int(call.data.split(":")[1])
    w = q("SELECT * FROM withdrawals WHERE id=?", (wid,), one=True)
    if not w or w["status"] != "pending":
        await call.answer("⚠️ আগেই প্রসেস হয়েছে", show_alert=True)
        return
    uid = int(w["user_id"])
    conn = connect()
    try:
        cur = conn.execute("UPDATE withdrawals SET status='rejected', decided_at=?, note='রিজেক্ট — টাকা ফেরত' WHERE id=? AND status='pending'", (now(), wid))
        if cur.rowcount != 1:
            conn.rollback()
            await call.answer("⚠️ এই উইথড্র ইতিমধ্যে প্রসেস হয়েছে।", show_alert=True)
            return
        conn.commit()
    finally:
        conn.close()
    add_balance(uid, float(w["amount"]))
    await call.message.answer(
        f"❌ <b>উইথড্র #{wid} রিজেক্ট — {taka(w['amount'])} ফেরত দেওয়া হয়েছে।</b>",
        reply_markup=kb([b("⬅️ উইথড্র লিস্ট", "wds:0")]),
    )
    await notify_user(
        uid,
        f"{DIV}\n❌ <b>উইথড্র রিজেক্ট হয়েছে</b>\n{DIV}\n\n"
        + box([f"💵 {money(w['method'], w['amount'])} আপনার ব্যালেন্সে ফেরত দেওয়া হয়েছে", f"👛 ব্যালেন্স: {money(w['method'], get_balance(uid))}"], "রিফান্ড", "♻️"),
        "❌ উইথড্র রিজেক্ট",
    )
    await call.answer("❌ রিজেক্ট হয়েছে")


