@dp.message(AdminFSM.premium_emoji_value, F.text)
async def admin_premium_emoji_value(message: Message, state: FSMContext) -> None:
    if not is_admin(message.from_user.id):
        await state.clear()
        return
    value = message.text.strip()
    if value.lower() == "/cancel":
        await state.clear()
        await message.answer("❎ বাতিল করা হয়েছে।")
        return
    if not value or len(value) > 100 or "\n" in value:
        await message.answer("⚠️ একটি ইমোজি অথবা custom emoji ID দিন।")
        return
    set_setting("premium_emoji_value", value)
    set_setting("premium_emoji_enabled", "1")
    await state.clear()
    await message.answer("✅ প্রিমিয়াম ইমোজি সেটিং সেভ হয়েছে।", reply_markup=kb([b("💎 প্রিমিয়াম ইমোজি", "premium_emoji", BLUE)], [b("👑 এডমিন প্যানেল", "admin")]))


