@dp.message(AdminFSM.setting_value, F.text)
async def admin_setting_value(message: Message, state: FSMContext) -> None:
    if not is_admin(message.from_user.id):
        await state.clear()
        return
    data = await state.get_data()
    key = data["setting_key"]
    value = message.text.strip()
    if key in ("refer_bonus", "min_withdraw", "usdt_rate"):
        try:
            number = float(value)
            if number < 0:
                raise ValueError
            value = str(number)
        except ValueError:
            await message.answer("⚠️ সঠিক ধনাত্মক সংখ্যা লিখুন! যেমন: <code>100</code>")
            return
    elif key == "agent_user_percent" or key.startswith("category_share:"):
        try:
            number = float(value.replace("%", "").strip())
            if not 0 <= number <= 100:
                raise ValueError
            value = str(number)
        except ValueError:
            await message.answer("⚠️ শতাংশ 0 থেকে 100-এর মধ্যে লিখুন। যেমন: <code>66.67</code>")
            return
        if key.startswith("category_share:"):
            cid = int(key.split(":", 1)[1])
            q("INSERT INTO category_shares(category_id, user_percent) VALUES(?, ?) ON CONFLICT(category_id) DO UPDATE SET user_percent=excluded.user_percent", (cid, float(value)))
            key = "category_share_saved"
    if key != "category_share_saved":
        set_setting(key, value)
    await state.clear()
    labels = {v[0]: v[1] for v in SETTING_LABELS.values()}
    if key == "category_share_saved":
        labels[key] = "ক্যাটাগরি ভিত্তিক ইউজার ভাগ"
    await message.answer(
        f"{DIV}\n✅ <b>সেটিংস আপডেট হয়েছে!</b>\n{DIV}\n\n"
        + box([f"{labels.get(key, key)}", f"🆕 নতুন ভ্যালু: <code>{esc(value)}</code>", f"🕒 {now()}"], "সফল", "⚙️"),
        reply_markup=kb([b("📂 ক্যাটাগরি ভাগ", "setcatsplit")], [b("⚙️ সেটিংস", "set")], [b("👑 এডমিন প্যানেল", "admin")]),
    )


