# ══════════════════════════ এডমিন: লেনদেন রিপোর্ট ══════════════════════════
@dp.callback_query(F.data.startswith("ltx:"))
async def cb_ledger(call: CallbackQuery) -> None:
    if not admin_only(call):
        await call.answer("⛔", show_alert=True)
        return
    try:
        _, page_s, inc_s, flt = call.data.split(":")
        page = max(0, int(page_s))
    except ValueError:
        await call.answer()
        return
    inc = inc_s == "1"                      # 1 = এডমিনের লেনদেনসহ
    if flt not in LEDGER_FILTERS:
        flt = "all"

    admin_cond, admin_params = "", []
    if not inc:
        ids = sorted(all_admin_ids())
        if ids:
            admin_cond = "user_id NOT IN (" + ",".join("?" * len(ids)) + ")"
            admin_params = list(ids)

    conds, params = ([admin_cond] if admin_cond else []), list(admin_params)
    kinds = LEDGER_FILTERS[flt]
    if kinds:
        conds.append("kind IN (" + ",".join("?" * len(kinds)) + ")")
        params += list(kinds)
    where = (" WHERE " + " AND ".join(conds)) if conds else ""
    sum_where = (" WHERE " + admin_cond) if admin_cond else ""

    total = q(f"SELECT COUNT(*) AS c FROM ledger{where}", tuple(params), one=True)["c"]
    per = 8
    pages = max(1, (total + per - 1) // per)
    page = min(page, pages - 1)
    rows_db = q(
        f"SELECT l.*, u.first_name, u.username FROM ledger l LEFT JOIN users u ON u.id=l.user_id"
        f"{where.replace('user_id', 'l.user_id').replace('kind', 'l.kind')} ORDER BY l.id DESC LIMIT ? OFFSET ?",
        tuple(params) + (per, page * per),
    )
    sums = {r["kind"]: (r["c"], r["s"]) for r in q(f"SELECT kind, COUNT(*) AS c, COALESCE(SUM(amount),0) AS s FROM ledger{sum_where} GROUP BY kind", tuple(admin_params))}

    summary = []
    for kind, (emoji, label) in LEDGER_KINDS.items():
        if kind in sums:
            c, s = sums[kind]
            summary.append(f"{emoji} <b>{label}</b>: {taka(abs(s))} ({c} বার)")
    scope = "এডমিনসহ সবার" if inc else "এডমিন বাদে সব ইউজারের"
    text = f"{head('🧾', 'লেনদেন রিপোর্ট', scope + ' লেনদেন')}\n\n"
    text += box(summary, "মোট হিসাব", "💰") if summary else "😔 এখনো কোনো লেনদেন হয়নি।"
    if rows_db:
        text += f"\n\n📋 <b>{LEDGER_FILTER_LABELS[flt]}</b> — পেজ {page + 1}/{pages}\n"
        for r in rows_db:
            emoji, label = LEDGER_KINDS.get(r["kind"], ("💳", r["kind"]))
            amt = float(r["amount"])
            sign = "+" if amt >= 0 else "−"
            who = esc(r["first_name"] or "ইউজার") + (f" @{esc(r['username'])}" if r["username"] else "")
            text += (
                f"\n{emoji} <b>{label}</b> • <b>{sign}{taka(abs(amt))}</b>\n"
                f"┃ 👤 {who} (<code>{r['user_id']}</code>)\n"
                f"┃ 📝 {esc(r['note'] or '-')}\n"
                f"┃ 🕒 {esc(r['created_at'])}\n"
            )

    filter_btns = [
        b(("✅ " if k == flt else "") + LEDGER_FILTER_LABELS[k], f"ltx:0:{1 if inc else 0}:{k}", GREEN if k == flt else None)
        for k in LEDGER_FILTERS
    ]
    nav = []
    if page > 0:
        nav.append(b("⬅️ আগেরটি", f"ltx:{page - 1}:{1 if inc else 0}:{flt}", None))
    if page < pages - 1:
        nav.append(b("পরেরটি ➡️", f"ltx:{page + 1}:{1 if inc else 0}:{flt}", None))
    rows = grid(filter_btns, 2)
    if nav:
        rows.append(nav)
    rows.append([b("👑 এডমিনের লেনদেন বাদ দিন" if inc else "👑 এডমিনের লেনদেনসহ দেখুন", f"ltx:0:{0 if inc else 1}:{flt}", BLUE)])
    rows.append([b("👑 এডমিন প্যানেল", "admin", None)])
    try:
        await call.message.edit_text(text, reply_markup=kb(*rows))
    except TelegramBadRequest:
        pass
    await call.answer()


